<?php
namespace Tests\Feature;
use App\Models\{Employee,User}; use Illuminate\Foundation\Testing\RefreshDatabase; use Laravel\Sanctum\Sanctum; use Tests\TestCase;
class PayrollApiTest extends TestCase {use RefreshDatabase; public function test_user_can_generate_payroll():void{$user=User::factory()->create();$employee=Employee::factory()->create(['base_salary'=>30000]);Sanctum::actingAs($user);$user->givePermissionTo('create payroll');$response=$this->postJson('/api/payrolls',['employee_id'=>$employee->id,'period_month'=>9,'period_year'=>2026]);$response->assertCreated()->assertJsonPath('data.net_pay',28200);$this->assertDatabaseHas('payrolls',['employee_id'=>$employee->id,'period_month'=>9]);} public function test_duplicate_period_is_rejected():void{$user=User::factory()->create();$employee=Employee::factory()->create();Sanctum::actingAs($user);$user->givePermissionTo('create payroll');$data=['employee_id'=>$employee->id,'period_month'=>1,'period_year'=>2026];$this->postJson('/api/payrolls',$data)->assertCreated();$this->postJson('/api/payrolls',$data)->assertStatus(500);}}
